func isRoleSelectedWeekly(role string, selectedRoles []string) bool {
	for _, r := range selectedRoles {
		if r == role {
			return true
		}
	}
	return false
}

func toSelectedRolesJSONWeekly(roles []string) string {
	jsonBytes, _ := json.Marshal(roles)
	return string(jsonBytes)
}

func formatHoursWeekly(n float64) string {
	s := fmt.Sprintf("%.1f", n)
	parts := strings.Split(s, ".")
	intPart := parts[0]
	decPart := parts[1]

	var result strings.Builder
	for i, c := range intPart {
		if i > 0 && (len(intPart)-i)%3 == 0 {
			result.WriteRune(',')
		}
		result.WriteRune(c)
	}

	return result.String() + "." + decPart
}

// getOverallProductivity calculates the productivity ratio across all authors
func getOverallProductivity(data []types.DailyHours) float64 {
	var totalAM, totalPR float64
	for _, item := range data {
		totalAM += item.AfterMarket
		totalPR += item.Project
	}
	if totalAM+totalPR == 0 {
		return 0
	}
	return totalPR / (totalAM + totalPR)
}

